args.command:
cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488593" | python3 -c "
import json,sys; d=json.load(sys.stdin)
for k in ['episode_id','phase','posting_deadline','challenge_deadline','content_hash','evidence_hash','content','evidence','creator_votes','challenger_votes','required_votes','total_deposited_wei']:
    print(k,':',d[k])
print('jurors:',[(j['actor_id'],j['commitment'],j['revealed'],j['verdict']) for j in d['jurors']])
"

cd /workspace && curl -s "$VERACITY_URL/v1/episodes/VR-488593/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print(len(d['messages']),'messages')
for m in d['messages']: print('---',m['sequence'],m['sender_id']); print(m['content'][:1500])
"; echo '--- chats ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488593/chats" | head -c 300

cd /workspace && cat > forum_body.json <<'EOF'
{"content":"Checked the Unit 4 readings for 1-30 September 2026. Billing uses actual readings only, so the 15 September estimated main-hall figure is not needed: M-0412 = 50,977.0 - 48,213.6 = 2,763.4 kWh and M-0413 = 12,902.9 - 12,040.2 = 862.7 kWh, a total of 3,626.1 kWh across the two meters, which exceeds 3,500 kWh by 126.1 kWh. Splitting M-0412 at the estimated mid-month figure gives the identical total (1,288.4 + 1,475.0 = 2,763.4), so the estimate does not change the result either way. Two things worth flagging: the main hall alone is 2,763.4 kWh, i.e. below the threshold, so the claim holds only because it is stated 'across its two meters'; and the margin is 126.1 kWh (about 3.5%), so a reading error of that size would matter, though the endpoints are stated to be actual engineer readings with no rollover or meter replacement and no other meters. Uncertainties: this document is the only evidence in the case and the readings are taken as printed. On the record as submitted the claim holds, so no challenge from me."}
EOF
curl -s -X POST "$VERACITY_URL/v1/episodes/VR-488593/forum/messages" -H "Content-Type: application/json" -H "Idempotency-Key: vr488593-forum-1" --data-binary @forum_body.json | python3 -c "
import json,sys; d=json.load(sys.stdin); print('seq',d['sequence'],d['sender_id'],d['content_hash'])
"

cd /workspace && curl -s "$VERACITY_URL/v1/episodes/VR-488593/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin)
print(len(d['messages']),'messages:',[m['sender_id'] for m in d['messages']])
for m in d['messages'][1:]:
    print('---',m['sequence'],m['sender_id']); print(m['content'][:1200])
"

cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488593" | python3 -c "
import json,sys; d=json.load(sys.stdin)
print('phase:',d['phase'],'| evidence:',d['evidence'],'| challenge_deadline:',d['challenge_deadline'])
print('hash:',d['content_hash'])
"; curl -s "$VERACITY_URL/v1/episodes/VR-488593/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('forum:',len(d['messages']),[m['sender_id'] for m in d['messages']])
"; curl -s "$VERACITY_URL/v1/episodes/VR-488593/chats" | head -c 200; echo; curl -s "$VERACITY_URL/v1/episodes/VR-488593/balances" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('credits:',d['withdrawal_credits']['challenger'])
"

cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488593" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('phase:',d['phase'],'| deposited:',d['total_deposited_wei'],'| credited:',d['total_credited_wei'])
"; echo '--- settlement ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488593/settlement" | python3 -m json.tool; echo '--- balances ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488593/balances" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('entitlements:',d['entitlements']); print('credits:',d['withdrawal_credits'])
"
